mapper.select:
select count(1)
from prompt_template
where (
    scope = 'GLOBAL'
)

    and scope = #{scope}


    and state = #{state}


    and (
        template_code like concat('%', #{keyword}, '%')
        or template_name like concat('%', #{keyword}, '%')
    )

select id, scope, template_code, template_name, version_no, state, content, variable_spec_json, created_by, updated_by, created_at, updated_at from prompt_template where ( scope = 'GLOBAL' )
and scope = #{scope}
and state = #{state}
and ( template_code like concat('%', #{keyword}, '%') or template_name like concat('%', #{keyword}, '%') )
order by scope asc, updated_at desc, id desc limit #{pageSize} offset #{offset}
